+    machine.sim = &s;
+    const id = try s.start(0, &.{});
+
+    const answered = try s.ask(id, try machine.variant("Keep", &.{.{ .handle = id }}), 1_000);
+    try std.testing.expectEqualStrings("Ok", answered.variant.name);
+    try std.testing.expectEqualStrings("waiter-owned", answered.variant.fields[0].string);
