snapshots.pack-errdefer-focused-test.patch:
--- a/toolchain/src/vm.zig
+++ b/toolchain/src/vm.zig
@@ -2690,3 +2690,35 @@ test "step 42: stress makes every region budget zero" {
     try std.testing.expectEqual(@as(usize, 0), vm.loop_budget);
     try std.testing.expectEqual(@as(usize, 0), vm.walk_budget);
 }
+
+test "step 42: pack frees its parcel when copying the payload runs out of memory" {
+    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{
+        .fail_index = 1,
+    });
+
+    var machine: Vm = .init(std.testing.allocator, undefined, 0);
+    var audit: ParcelAudit = .{};
+    machine.parcel_audit = &audit;
+    machine.parcel_allocator = failing.allocator();
+    try std.testing.expectError(
+        error.OutOfMemory,
+        machine.pack(.{ .string = "copy me into the parcel" }),
+    );
+    const counts = audit.snapshot();
+    std.debug.print(
+        "step42 pack-errdefer allocator allocations={d} deallocations={d} allocated_bytes={d} freed_bytes={d}\n",
+        .{ failing.allocations, failing.deallocations, failing.allocated_bytes, failing.freed_bytes },
+    );
+    std.debug.print(
+        "step42 parcel-audit case=pack-errdefer allocated={d} destroyed={d} live={d}\n",
+        .{ counts.allocated, counts.destroyed, counts.allocated - counts.destroyed },
+    );
+    try std.testing.expect(failing.has_induced_failure);
+    try std.testing.expectEqual(@as(usize, 1), failing.allocations);
+    try std.testing.expectEqual(@as(usize, 1), failing.deallocations);
+    try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
+
+    try std.testing.expectEqual(@as(usize, 1), counts.allocated);
+    try std.testing.expectEqual(@as(usize, 1), counts.destroyed);
+    try std.testing.expectEqual(counts.allocated, counts.destroyed);
+}
